const allItems = $input.all() || [];

// ---------------- Helpers ----------------

// Item foliar = tem o array foliarApplicationAdvices dentro de response[0].
// Só item foliar tem isso, então não depende do nome do "type".
function isFoliarItem(json) {
  return Array.isArray(json?.response?.[0]?.foliarApplicationAdvices);
}

// Helper único: percorre todos os itens de entrada e retorna o primeiro valor
// não-nulo encontrado pelo `getter`. Usa optional chaining (?.) então não
// quebra se o caminho não existir naquele item específico — só passa pro próximo.
// `accept` (opcional) decide quais itens podem ser considerados.
// try/catch: se um item vier malformado, pula pro próximo em vez de quebrar o nó.
function findValue(getter, accept = null) {
  for (const item of allItems) {
    const json = item?.json;
    if (!json) continue;
    if (accept && !accept(json)) continue;
    try {
      const val = getter(json);
      if (val != null) return val;
    } catch (e) {
      // ignora item com estrutura inesperada
    }
  }
  return null;
}

// Só manda para a IA o tipo de análise que realmente existe (evita erro/timeout quando o setor não tem, por ex., análise foliar)
function hasData(v) {
  if (v == null) return false;
  if (typeof v === "string") return v.trim() !== "";
  if (Array.isArray(v)) return v.length > 0;
  if (typeof v === "object") return Object.keys(v).length > 0;
  return true;
}

const notFoliar = (json) => !isFoliarItem(json);

// ---------------- Solo (mesmos caminhos de antes, só ignorando item foliar) ----------------
const plantAdvices    = findValue((json) => json.response?.[0]?.plantingAdvices,    notFoliar);
const soilAnalyses    = findValue((json) => json.response?.[0]?.analysis,           notFoliar);
const fertilizerPlans = findValue((json) => json.response?.[0]?.fertilizationPlans, notFoliar);
const soilAnalysisHistory = findValue((json) => json.soilAnalysisHistory);

// ---------------- Foliar ----------------
// Aceita o formato antigo (campo na raiz) e o formato atual (dentro de response[0]).
const foliarApplicationAdvices = findValue((json) =>
  json.foliarApplicationAdvices ??
  (isFoliarItem(json) ? json.response[0].foliarApplicationAdvices : null)
);
const leafTissueAnalysis = findValue((json) =>
  json.leafTissueAnalysis ??
  (isFoliarItem(json) ? json.response[0].analysis : null)
);
const foliarAnalysis = findValue((json) => json.foliarAnalysis);
const applications   = findValue((json) => json.applications);

// ---------------- Saída (formato idêntico ao anterior) ----------------
let response = [
  // { json: { field: "plantAdvices", value: plantAdvices } },
  { json: { field: "soilAnalyses", value: hasData(soilAnalyses) ? {soilAnalyses, fertilizerPlans, plantAdvices} : null } },
//  { json: { field: "fertilizerPlans", value: fertilizerPlans } },
  { json: { field: "soilAnalysisHistory", value: hasData(soilAnalysisHistory) ? soilAnalysisHistory : null } },
  { json: { field: "leafTissueAnalysis", value: hasData(leafTissueAnalysis) ? {leafTissueAnalysis, foliarApplicationAdvices} : null } },
  //  { json: { field: "foliarProductivity", value: {foliarAnalysis,applications} } },

    // { json: { field: "noMatch", value: null } },
];

response = response.filter(item => item.json.value != null);
return response;

const items = $input.all();
const result = {};

// Se vier { blocos: [...] }, pega só o array
const unwrap = (v) => {
  if (typeof v === 'string') {
    try { v = JSON.parse(v); } catch (e) { return v; }
  }
  if (v && !Array.isArray(v) && typeof v === 'object' && Array.isArray(v.blocos)) {
    return v.blocos;
  }
  return v;
};

const toJsonOrEmpty = (v) => {
  v = unwrap(v);
  if (v === null || v === undefined) return '';
  if (typeof v === 'string') {
    const s = v.trim();
    return ['', 'none', 'null', 'undefined', '[]', '{}'].includes(s) ? '' : s;
  }
  if (Array.isArray(v) && v.length === 0) return '';
  if (typeof v === 'object' && Object.keys(v).length === 0) return '';
  return JSON.stringify(v);
};

for (const item of items) {
  const body = item.json.body;
  if (!body || !body.type || !body.result) continue;
  result[body.type] = toJsonOrEmpty(body.result);
}

for (const f of ['soilAnalyses', 'soilAnalysisHistory', 'leafTissueAnalysis']) {
  if (result[f] === undefined) result[f] = '';
}

return [{ json: result }];

// n8n Code Node — modo "Run Once for All Items"

try {
  const inputItem = $input.first();
  if (!inputItem || !inputItem.json) {
    return [{ json: { error: "No input item received." } }];
  }

  const input = inputItem.json;

  // CORREÇÃO 1: Acessar input.response e extrair o objeto 'analysis' de cada item
  const responses = Array.isArray(input.response) ? input.response : [];
  const validAnalyses = responses
    .map(r => r.analysis)
    .filter((a) => a && typeof a === "object");

  if (validAnalyses.length === 0) {
    return [{ json: { error: "No valid analyses found in payload." } }];
  }

const targetSectorId = input.sectorId ?? null;

let first = validAnalyses[0];
let sectorRaw = (Array.isArray(first.sectors) && first.sectors[0]) || {};

if (targetSectorId) {
  for (const a of validAnalyses) {
    const match = (Array.isArray(a.sectors) ? a.sectors : []).find(
      (s) => s && s._id === targetSectorId
    );
    if (match) {
      first = a;
      sectorRaw = match;
      break;
    }
  }
}

  const sector = {
    name: sectorRaw.name ?? null,
    size: sectorRaw.size ?? null,
    plantingDate: sectorRaw.plantingDate ? String(sectorRaw.plantingDate).split("T")[0] : null,
    amountOfPlants: sectorRaw.amountOfPlants ?? null,
    plantSpacing: sectorRaw.plantSpacing ?? null,
    lineSpacing: sectorRaw.lineSpacing ?? null,
  };

  const property = {
    name: first.prop?.name ?? null,
    state: first.prop?.state ?? null,
  };

  const area = {
    name: first.area?.name ?? null,
    culture: first.area?.culture ?? null,
  };

  const sectorIdRef = sectorRaw._id ?? null;
  const propertyIdRef = first.prop?._id ?? null;
  const areaIdRef = first.area?._id ?? null;

  const warnings = [];
  const samples = [];

  for (const a of validAnalyses) {
    if (!a.name) {
      warnings.push("An analysis without 'name' was skipped.");
      continue;
    }

    const s = (Array.isArray(a.sectors) && a.sectors[0]) || {};
    if (sectorIdRef && s._id !== sectorIdRef) warnings.push(`Sample "${a.name}" belongs to a different sector.`);
    if (propertyIdRef && a.prop?._id !== propertyIdRef) warnings.push(`Sample "${a.name}" belongs to a different property.`);
    if (areaIdRef && a.area?._id !== areaIdRef) warnings.push(`Sample "${a.name}" belongs to a different area.`);

    const parsedValues = {};

    // CORREÇÃO 2: Ler diretamente de a.values, que contém as chaves e valores diretos (ex: "K": 122)
    const sourceValues = a.values && typeof a.values === "object" ? a.values : {};

    for (const [param, val] of Object.entries(sourceValues)) {
      if (val === null || val === undefined) {
        warnings.push(`Parameter "${param}" in sample "${a.name}" has no value and was skipped.`);
        continue;
      }

      // Mantém apenas o valor. Como o payload não tem mais unidades complexas separadas, o dictionary de conversions foi removido.
      parsedValues[param] = val; 
    }

    const sampledAt = a.sampledAt ? String(a.sampledAt).split("T")[0] : null;

    samples.push({
      name: a.name,
      sampledAt,
      values: parsedValues,
    });
  }

  // Ordenar por data de amostragem
  samples.sort((x, y) => {
    const tX = x.sampledAt ? new Date(x.sampledAt).getTime() : Infinity;
    const tY = y.sampledAt ? new Date(y.sampledAt).getTime() : Infinity;
    return tX - tY;
  });

  const validDates = samples.map((s) => s.sampledAt).filter(Boolean);
  const uniqueDates = [...new Set(validDates)];

  const output = {
    sector,
    property,
    area,
    totalSamples: samples.length,
    distinctDates: uniqueDates.length,
    period: {
      start: validDates[0] || null,
      end: validDates[validDates.length - 1] || null,
    },
    samples,
    ...(warnings.length > 0 ? { warnings } : {}),
    chatInput: ""
  };

  return { json: {soilAnalysisHistory:output, }};

} catch (err) {
  const message = err instanceof Error ? err.message : String(err);
  const stack = err instanceof Error ? err.stack : null;
  return [{ json: { error: true, message, stack } }];
}

// n8n Code Node — modo "Run Once for All Items"
try {
  const nz = function (v, d) { return (v === undefined || v === null) ? (d === undefined ? null : d) : v; };

  const inputItem = $input.first();
  if (!inputItem || !inputItem.json) {
    return [{ json: { error: "No input item received." } }];
  }
  const input = inputItem.json;

  const responses = Array.isArray(input.response) ? input.response : [];
  const validEntries = responses.filter(function (r) { return r && r.analysis && typeof r.analysis === "object"; });
  if (validEntries.length === 0) {
    return [{ json: { error: "No valid foliar analyses found in payload." } }];
  }

  const first = validEntries[0].analysis;
  const sectorRaw = (Array.isArray(first.sectors) && first.sectors[0]) || {};
  const sector = {
    name: nz(sectorRaw.name),
    size: nz(sectorRaw.size),
    plantingDate: sectorRaw.plantingDate ? String(sectorRaw.plantingDate).split("T")[0] : null,
    amountOfPlants: nz(sectorRaw.amountOfPlants),
    plantSpacing: nz(sectorRaw.plantSpacing),
    lineSpacing: nz(sectorRaw.lineSpacing)
  };
  const property = { name: nz(first.prop && first.prop.name), state: nz(first.prop && first.prop.state) };
  const area = { name: nz(first.area && first.area.name), culture: nz(first.area && first.area.culture) };

  const sectorIdRef = nz(sectorRaw._id);
  const propertyIdRef = nz(first.prop && first.prop._id);
  const areaIdRef = nz(first.area && first.area._id);

  const warnings = [];
  const samples = [];

  for (let i = 0; i < validEntries.length; i++) {
    const entry = validEntries[i];
    const a = entry.analysis;
    if (!a.name) {
      warnings.push("An analysis without 'name' was skipped.");
      continue;
    }
    const s = (Array.isArray(a.sectors) && a.sectors[0]) || {};
    if (sectorIdRef && s._id !== sectorIdRef) warnings.push('Sample "' + a.name + '" belongs to a different sector.');
    if (propertyIdRef && a.prop && a.prop._id !== propertyIdRef) warnings.push('Sample "' + a.name + '" belongs to a different property.');
    if (areaIdRef && a.area && a.area._id !== areaIdRef) warnings.push('Sample "' + a.name + '" belongs to a different area.');

    // Valores nutricionais foliares (N, P, K, Ca, Mg, S, B, Cu, Fe, Mn, Zn)
    const parsedValues = {};
    const sourceValues = a.values && typeof a.values === "object" ? a.values : {};
    for (const param in sourceValues) {
      const val = sourceValues[param];
      if (val === null || val === undefined) {
        warnings.push('Parameter "' + param + '" in sample "' + a.name + '" has no value and was skipped.');
        continue;
      }
      parsedValues[param] = val;
    }

    // Recomendações de adubação foliar vinculadas a esta análise (se houver)
    const advicesRaw = Array.isArray(entry.foliarApplicationAdvices) ? entry.foliarApplicationAdvices : [];
    const advices = advicesRaw.map(function (adv) {
      return {
        name: nz(adv.name),
        applicationDate: adv.applicationDate ? String(adv.applicationDate).split("T")[0] : null,
        products: (Array.isArray(adv.products) ? adv.products : []).map(function (p) {
          return {
            name: nz(p.productCommercialName && p.productCommercialName.name),
            class: nz(p.productClass),
            dose: nz(p.dose),
            unit: nz(p.doseMeasurementUnit)
          };
        })
      };
    });

    const sampleAt = a.sampleAt ? String(a.sampleAt).split("T")[0] : null;
    samples.push({
      name: a.name,
      sampleAt: sampleAt,
      season: nz(a.season),
      region: nz(a.region),
      biennial: nz(a.biennial),
      note: nz(a.note),
      values: parsedValues,
      linkedToAdvice: a.linkedToAdvice ? true : false,
      advices: advices
    });
  }

  samples.sort(function (x, y) {
    const tX = x.sampleAt ? new Date(x.sampleAt).getTime() : Infinity;
    const tY = y.sampleAt ? new Date(y.sampleAt).getTime() : Infinity;
    return tX - tY;
  });

  const validDates = samples.map(function (s) { return s.sampleAt; }).filter(Boolean);
  const uniqueDates = validDates.filter(function (v, idx, arr) { return arr.indexOf(v) === idx; });

  const output = {
    sector: sector,
    property: property,
    area: area,
    totalSamples: samples.length,
    distinctDates: uniqueDates.length,
    period: { start: validDates[0] || null, end: validDates[validDates.length - 1] || null },
    samples: samples,
    chatInput: ""
  };
  if (warnings.length > 0) output.warnings = warnings;
const foliarApplicationAdvices = $input.first().json.response[0].foliarApplicationAdvices
  return { json: { leafTissueAnalysis: output, foliarApplicationAdvices} };
} catch (err) {
  const message = err instanceof Error ? err.message : String(err);
  const stack = err instanceof Error ? err.stack : null;
  return [{ json: { error: true, message: message, stack: stack } }];
}

